package com.collabspace.controller; import com.collabspace.dto.ChannelDtos.*; import com.collabspace.service.ChannelService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequiredArgsConstructor public class ChannelController {private final ChannelService s; @GetMapping("/api/workspaces/{workspaceId}/channels") public List<ChannelResponse> list(@PathVariable UUID workspaceId){return s.list(workspaceId);}@PostMapping("/api/workspaces/{workspaceId}/channels") public ChannelResponse create(@PathVariable UUID workspaceId,@Valid @RequestBody CreateChannelRequest r){return s.create(workspaceId,r);}@PutMapping("/api/channels/{id}") public ChannelResponse update(@PathVariable UUID id,@Valid @RequestBody UpdateChannelRequest r){return s.update(id,r);}@DeleteMapping("/api/channels/{id}") public void delete(@PathVariable UUID id){s.delete(id);}@PostMapping("/api/channels/{id}/join") public void join(@PathVariable UUID id){s.join(id);}@PostMapping("/api/channels/{id}/leave") public void leave(@PathVariable UUID id){s.leave(id);}}